class PeekingIterator:
    def __init__(self, iterator):
        self.iterator = iterator
        self.cached = None
        self.has_cached = False

    def peek(self):
        if not self.has_cached:
            self.cached = self.iterator.next()          # pull one ahead, cache it
            self.has_cached = True
        return self.cached

    def next(self):
        if self.has_cached:
            self.has_cached = False                        # drain the cache
            return self.cached
        return self.iterator.next()

    def has_next(self):
        return self.has_cached or self.iterator.has_next()

