import java.util.*;

class PeekingIterator implements Iterator<Integer> {
    Iterator<Integer> iterator;
    Integer cached = null;
    boolean hasCached = false;

    PeekingIterator(Iterator<Integer> iterator) {
        this.iterator = iterator;
    }

    public Integer peek() {
        if (!hasCached) {
            cached = iterator.next();                        // pull one ahead, cache it
            hasCached = true;
        }
        return cached;
    }

    public Integer next() {
        if (hasCached) {
            hasCached = false;                                 // drain the cache
            return cached;
        }
        return iterator.next();
    }

    public boolean hasNext() {
        return hasCached || iterator.hasNext();
    }
}

